def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if platform.system() == "Windows":
        python = 'python'
        if cmd[0].startswith('/'):
            python = 'cmd /k "set PATH=%PATH%;C:\\Python38" & python'
        elif cmd[0].startswith('C:'):
            python = 'cmd /k "set PATH=%PATH%;C:\\Python38" & python'
        elif cmd[0].startswith('..'):
            python = 'cmd /k "set PATH=%PATH%;C:\\Python38" & python'
        else:
            python = 'python'
        return (python,) + cmd[1:]

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if platform.system() == "Windows":
        cmd_ = []
        for token in cmd:
            if token.startswith(":"):
                if token == ":":
                    # empty path
                    cmd_.append("")
                else:
                    # absolute path
                    cmd_.append(token[1:])
            else:
                # relative path
                cmd_.append(token)
        return tuple(cmd_)
    return cmd

