        # nonlocal workaround to support Python 2
        # https://technotroph.wordpress.com/2012/10/01/python-closures-and-the-python-2-7-nonlocal-solution/
        d = {'_size': 0, 'items': {}, '_size_limit': maxsize}

        @functools.wraps(f)
        def _wrapped(*args, **kwargs):
            # If the key is in the cache then it's the most recently used
            # so move it to the end of the list
            key = (args, tuple(kwargs.items()))
            try:
                d['items'][key]
            except KeyError:
                d['items'][key] = True
                d['_size'] += 1
                if d['_size'] > d['_size_limit']:
                    oldest = min(d['items'].items(),
                            key=lambda i: i[1])[0]
                    del d['items'][oldest]
            return f(*args, **kwargs)

        return _wrapped

    return _wrapper

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

