        # https://technotroph.wordpress.com/2012/10/01/python-closures-and-the-python-2-7-nonlocal-solution/
        d = {'cache': OrderedDict()}

        @functools.wraps(f)
        def _wrapped(*args, **kwargs):
            try:
                result = d['cache'][args, frozenset(kwargs)]
            except (KeyError, TypeError):
                result = f(*args, **kwargs)
                d['cache'][args, frozenset(kwargs)] = result
                if len(d['cache']) > maxsize:
                    least_recently_used = d['cache'].pop(
                        d['cache'].keys()[0]
                    )
                    d['cache'][args, frozenset(kwargs)] = result
            return result

        return _wrapped

    return _wrapper

