    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = collections.LFUCache(maxsize) if maxsize else {}
        return wraps(func)(partial(_memoized_call, func, cache))
    return decorator

