def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent.
    """
    uniqueClasses = []
    for cls in classes:
        if cls not in uniqueClasses:
            uniqueClasses.append(cls)
    minimal = []
    for cls in uniqueClasses:
        if all(base not in minimal for base in cls.__bases__):
            minimal.append(cls)
    while True:
        newMinimal = []
        for cls in minimal:
            for base in cls.__bases__:
                if base not in uniqueClasses:
                    continue
                if all(b not in cls.__bases__ for b in base.__bases__):
                    newMinimal.append(base)
        if newMinimal == minimal:
            break
        minimal = newMinimal
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = set(classes)
    seen = set()
    while True:
        newBases = set()
        for cls in bases:
            for base in cls.__bases__:
                if base not in seen:
                    newBases.add(base)
                    seen.add(base)
        if newBases == bases:
            break
        bases = newBases
    return list(bases)

