def generate_default_observer_schema(app):
    from krake.data.kubernetes import ResourceManifest
    from krake.data.observer import ObserverSchema

    # get the application's manifest
    manifest = app.spec.manifest

    # create a dictionary to store the default observer schemas
    default_schemas = dict()

    # iterate over the Kubernetes resources present in the manifest
    for resource in manifest.resources:
        # skip resources for which a custom observer schema has already been specified
        if resource.spec.observer_schema is not None:
            continue

        # create a new observer schema for the resource
        schema = ObserverSchema(resource.spec.template)

        # set the schema's fields based on the resource's template
        for field, spec in schema.fields.items():
            field_type = spec.type
            if field == "uid":
                field_type = str
            if field == "name":
                field_type = str
            if field == "namespace":
                field_type = str
            if field == "creation_timestamp":
                field_type = float
            if field == "generation":
                field_type = int
            if field == "annotations":
                field_type = dict
            if field == "labels":
                field_type = dict
            if field == "spec":
                field_type = ResourceManifest.resources[0].spec.template
            if field == "status":
                field_type = dict
            if field == "owner_name":
                field_type = str
            if field == "owner_kind":
                field_type = str
            if field == "owner_uid":
                field_type = str
            if field == "finalizers":
                field_type = list
            if field == "self_link":
                field_type = str

            schema.fields[field].type = field_type

        # add the default schema for the resource
        default_schemas[resource.name] = (ResourceManifest.resources[0].spec.template, schema)

    return default_schemas

