def format(sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :param params: The set of in-style parameters. It maps each parameter
                   to a value.
    :return: A tuple containing the formatted SQL query and the set of
             converted out-style parameters.
    """
    out_params = {}
    if params is not None:
        if isinstance(params, dict):
            for k, v in params.items():
                out_params[k] = v
        else:
            for i, p in enumerate(params):
                out_params[str(i)] = p
    return sql, out_params

