    """
    Extract the number and supplement from the content of an <issue> element.

    Values possible:
    * 5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl 1,
      25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
      s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
      suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    # Split the content by " " and clean it
    numbers = issue.text.split(" ")[1:-1]

    # Initialize the result variables
    number = None
    supplement = None

    # Iterate over the numbers and extract the number and supplement
    for n in numbers:
        if number is None and supplement is None:
            # Look for the first number in the list
            try:
                number = int(n)
            except ValueError:
                continue
        elif supplement is None:
            # If we get here, we have already found a number, look for supplement
            if n.endswith("suppl"):
                supplement = int(n[:-4])
            elif n[:2] == "Supp":
                supplement = int(n[4:])
            elif n[0] == "s":
                supplement = int(n[1:])
            else:
                continue

    return number, supplement

