    """
    Return a pretty formatted representation of self.

    @param indent: #int level of indentation
    @param debug: #bool flag indicating that debug information should be included
    @type indent: int
    @type debug: bool
    @returns: #str pretty formatted representation of self
    """

    # setup indentation string
    space = ' ' * indent

    # include debug information, if requested
    if debug:
        text = f'{space}DEBUG: Pretty printing object {type(self)}\n'
    else:
        text = ''

    # determine how we should print the object
    if isinstance(self, str):
        # if the obj is a string, just print it
        text += f'{space}{self}'
    elif isinstance(self, list):
        # if the obj is a list, print each element recursively
        for idx, elem in enumerate(self):
            text += f'{space}["{idx}"]'
            text += elem.pretty(indent + 2, debug)
    elif isinstance(self, dict):
        # if the obj is a dict, print each key-value pair recursively
        for key, val in self.items():
            text += f'{space}["{key}"]'
            text += val.pretty(indent + 2, debug)
    else:
        # if the obj is any other type, just print its class name
        text += f'{space}{type(self).__name__}'

    # return the pretty-printed text
    return text

