def parse_xrd_as_dict(xml: ElementTree.Element) -> Dict:
    """
    Parse XRD XML document as dictionary.

    https://tools.ietf.org/html/rfc6415
    """
    data = {}
    for node in xml.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Data'):
        type = node.attrib.get('type')
        value = node.attrib.get('value')
        if not (type and value):
            continue
        if type not in data:
            data[type] = []
        data[type].append(value)
    return data

