                raise IRValidatorException(f'Field "{key}" has invalid value "{value}"')

    # 4. Returns validated data
    return data

def validate_from_content(spec_content):
    """Validates that spec (YAML) content has all required fields.

    :param spec_content: Content of spec file.
    :raise IRValidatorException: When mandatory data is missing in spec file.
    :return: Dictionary with data loaded from a spec (YAML) file.
    """

    # check that all mandatory fields are present in spec content
    mandatory_fields = ["version", "name", "display_name", "description", "type", "format", "metadata"]
    for field in mandatory_fields:
        if field not in spec_content:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in spec content.")

    # check that all referenced components are present in the spec content
    # (e.g., datasets, connections, flows)
    component_types = ["datasets", "connections", "flows"]
    for component_type in component_types:
        if component_type in spec_content:
            for component_name in spec_content[component_type]:
                if component_name not in spec_content:
                    raise IRValidatorException(f"Component '{component_name}' is referenced in '{component_type}' but is missing from the spec content.")

    # check that all component references are valid
    for component_type in spec_content:
        if component_type in ["datasets", "connections", "flows"]:
            for component_name in spec_content[component_type]:
                if component_name not in spec_content:
                    raise IRValidatorException(f"Component '{component_name}' is invalid in '{component_type}'.")

    # check that the spec content has a valid version
    try:
        SemanticVersion(spec_content["version"])
    except ValueError:
        raise IRValidatorException("Invalid version in spec content.")

    # check that the spec content has a valid format
    if spec_content["format"] != "ir":
        raise IRValidatorException(f"Spec content does not have a valid format ({spec_content['format']}.")

    return spec_content

