def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    Args:
        vars_dict (dict): Dictionary to merge extra-vars into
        extra_vars (list, optional): List of extra-vars. Defaults to None.

    Examples:
        >>> vars_dict = {'var1': 'val1'}
        >>> extra_vars = [{'var2': 'val2'}, {'var3': 'val3'}]
        >>> merge_extra_vars(vars_dict, extra_vars)
        {'var1': 'val1', 'var2': 'val2', 'var3': 'val3'}

    """
    if extra_vars is None:
        return vars_dict
    else:
        for extra_var in extra_vars:
            key = list(extra_var.keys())[0]
            value = extra_var[key]
            vars_dict[key] = value

    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for option, value in values_dict.items():
        try:
            option_info = self._parser_options[parser_name][option]
            if option_info.type_:
                if option_info.type_ in [int, float]:
                    values_dict[option] = option_info.type_(value)
                elif option_info.type_ == bool:
                    values_dict[option] = value.lower() in ["true", "True", "1"]
        except KeyError:
            pass
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = self._create_parser(parser_name)

    for opt in parser:
        if opt.option_strings:
            # check for the key in the values_dict
            if opt.dest in values_dict:
                # convert the value to the correct type
                values_dict[opt.dest] = opt.convert(values_dict[opt.dest])
            else:
                # if the key is not in the values_dict,
                # and there is a default value, use that
                if opt.default is not None:
                    values_dict[opt.dest] = opt.convert(opt.default)

