    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    command_parser = self.command_line_parsers[parser_name]
    for argname in values_dict.keys():
        option = command_parser._option_string_actions.get(argname)
        if option is not None and option.action == "store":
            try:
                values_dict[argname] = option.type(values_dict[argname])
